    throw new Error(`${label}.digest: must be a sha256 hex digest`);
  }
  const tokenCount = rawTokenCount === null ? null : rawTokenCount;
  return {
    filesReadFully,
    filesTriagedByName,
    summary: {
      readCount,
      tokenCount,
    },
    digest: record.digest,
  };
}

